// API manager 2.2.0 — generated by tools/build.cjs.
// One entry describes one credential and one model. Labels are independent of
// the endpoint, and neither the endpoint nor the credential is an entry ID.
const catalogFormat = 'st-api-manager-catalog';
const makeId = () => Array.from(crypto.getRandomValues(new Uint8Array(16)), n => n.toString(16).padStart(2, '0')).join('');
const isObject = value => !!value && typeof value === 'object' && !Array.isArray(value);
const isText = value => typeof value === 'string';
const labels = value => Array.from(new Set(value.filter(id => isText(id) && id)));
const emptyCatalog = () => ({ format: catalogFormat, version: 2, entries: [], groups: [] });
const formatError = () => new Error('配置文件格式无效，原有配置已保留。');

function validateCatalog(value) {
  if (!isObject(value) || value.format !== catalogFormat || value.version !== 2 ||
      !Array.isArray(value.entries) || !Array.isArray(value.groups)) throw formatError();
  const groups = new Set();
  for (const group of value.groups) {
    if (!isObject(group) || !isText(group.id) || !group.id || groups.has(group.id) ||
        !isText(group.name) || !group.name.trim()) throw formatError();
    groups.add(group.id);
  }
  const entries = new Set();
  for (const row of value.entries) {
    if (!isObject(row) || !row.id || !isText(row.id) || entries.has(row.id) ||
        ![row.site, row.name, row.source, row.url, row.model, row.key].every(isText) ||
        !Array.isArray(row.groupIds) || row.groupIds.some(id => !groups.has(id))) throw formatError();
    entries.add(row.id);
  }
  return value;
}

function migrateCatalog(configs, categories = []) {
  const catalog = emptyCatalog();
  if (!Array.isArray(categories)) throw formatError();
  // Keep legacy IDs, colors and order; resolve category names used by older
  // exports. Unknown category references remain usable instead of disappearing.
  for (const category of categories) {
    if (!isObject(category) || !isText(category.name) || !category.name.trim()) throw formatError();
    const id = category.id || makeId();
    catalog.groups.push({ ...category, id });
  }
  const groupId = value => {
    const match = catalog.groups.find(group => group.id === value) ?? catalog.groups.find(group => group.name === value);
    if (match) return match.id;
    catalog.groups.push({ id: value, name: value });
    return value;
  };
  if (isObject(configs) && configs.format === 'grouped-api-configs' && Array.isArray(configs.groups)) {
    configs = configs.groups.flatMap(site => {
      if (!isObject(site) || !isText(site.groupName) || !isText(site.source) ||
          (site.models !== undefined && !Array.isArray(site.models))) throw formatError();
      const { models, ...shared } = site;
      return (models?.length ? models : [{}]).map(model => {
        if (!isObject(model)) throw formatError();
        return { ...shared, ...model };
      });
    });
  }
  if (!Array.isArray(configs)) throw formatError();
  for (const config of configs) {
    if (!isObject(config) || !isText(config.source) || !config.source ||
        (config.apiKeys !== undefined && !Array.isArray(config.apiKeys)) ||
        (config.categoryIds !== undefined && !Array.isArray(config.categoryIds))) throw formatError();
    const site = config.groupName || config.name || config.customUrl || '未命名站点';
    const model = config.customModel ?? '';
    const groupIds = labels(labels([...(config.categoryIds ?? []), config.categoryId]).map(groupId));
    const pool = config.apiKeys?.length ? [...config.apiKeys] : [];
    if (config.apiKey !== undefined && !pool.some(item => item?.key === config.apiKey)) pool.push({ key: config.apiKey });
    for (const [index, credential] of (pool.length ? pool : [{ key: '' }]).entries()) {
      if (!isObject(credential) || !isText(credential.key)) throw formatError();
      const { key, ...keyHistory } = credential;
      const { currentKeyIndex, enableKeyRotation, isActive, lastVerifiedAt, lastVerifiedKeyIndex, lastHealthStatus, lastHealthError } = config;
      catalog.entries.push({
        id: makeId(), site, name: config.name || '', source: config.source,
        url: config.customUrl ?? '', model, key, groupIds,
        history: { index, poolSize: pool.length, keyHistory, currentKeyIndex, enableKeyRotation, isActive, lastVerifiedAt, lastVerifiedKeyIndex, lastHealthStatus, lastHealthError },
      });
    }
  }
  return validateCatalog(catalog);
}

function readCatalog(value) {
  if (value?.format === catalogFormat) return { catalog: validateCatalog(value), legacy: false };
  if (Array.isArray(value) || value?.format === 'grouped-api-configs') return { catalog: migrateCatalog(value), legacy: true };
  if (!isObject(value) || !(value.configStore || Array.isArray(value.configs))) throw formatError();
  return { catalog: migrateCatalog(value.configStore ?? value.configs, value.categories), legacy: true };
}

// Compare values independently of JSON property order. Signatures stay in
// memory; keys are never embedded in IDs, DOM attributes, or sync metadata.
function canonical(value) {
  if (Array.isArray(value)) return '[' + value.map(canonical).join(',') + ']';
  if (isObject(value)) return '{' + Object.keys(value).filter(key => value[key] !== undefined).sort()
    .map(key => JSON.stringify(key) + ':' + canonical(value[key])).join(',') + '}';
  return JSON.stringify(value);
}
const withoutId = ({ id, ...value }) => canonical(value);
const conflictContent = ({ id, conflictSourceId, ...value }) => canonical(value);

function mergeCatalogRecords(local, incoming, legacy) {
  const records = [...local];
  const byId = new Map(local.map(record => [record.id, record]));
  const reservedIds = new Set(incoming.map(record => record.id));
  const ids = new Map();
  for (const record of incoming) {
    const existing = byId.get(record.id);
    let result;
    if (existing && canonical(existing) === canonical(record)) {
      result = existing;
    } else if (existing) {
      // Reuse only a copy made for this ID. An independent record can have
      // identical contents, even if it is absent from the imported subset.
      const content = conflictContent(record);
      result = local.find(candidate => !reservedIds.has(candidate.id) &&
        candidate.conflictSourceId === record.id && conflictContent(candidate) === content);
    } else if (legacy) {
      const content = withoutId(record);
      result = local.find(candidate => !reservedIds.has(candidate.id) && withoutId(candidate) === content);
    }
    if (!result) {
      result = existing ? { ...record, id: makeId(), conflictSourceId: record.id } : record;
      records.push(result);
    }
    reservedIds.add(result.id);
    ids.set(record.id, result.id);
  }
  return { records, ids };
}

function mergeCatalogs(local, incoming, legacy = false) {
  const { records: groups, ids: groupIds } = mergeCatalogRecords(local.groups, incoming.groups, legacy);
  const incomingEntries = incoming.entries.map(row => ({ ...row, groupIds: row.groupIds.map(id => groupIds.get(id)) }));
  const { records: entries } = mergeCatalogRecords(local.entries, incomingEntries, legacy);
  return { ...local, entries, groups };
}

const defaultEndpoints = {
  openai: 'https://api.openai.com/v1', deepseek: 'https://api.deepseek.com/v1',
  makersuite: 'https://generativelanguage.googleapis.com/v1beta',
};
function endpointUrl(value) {
  let url;
  try { url = new URL(value); } catch { throw new Error('请填写完整的 HTTP 或 HTTPS 站点地址。'); }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) {
    throw new Error('站点地址须为 HTTP 或 HTTPS，密钥请填在单独的密钥栏。');
  }
  return url;
}

async function discoverModels({ source, url, key }, request) {
  const google = source === 'makersuite';
  if (source !== 'custom' && !Object.hasOwn(defaultEndpoints, source)) {
    throw new Error('此来源请手动填写模型名。');
  }
  const target = endpointUrl(url.trim() || defaultEndpoints[source]);
  const base = target.pathname.replace(/\/+$/, '').replace(/\/(?:chat\/completions|models)$/, '');
  target.pathname = (base || (google ? '/v1beta' : '/v1')) + '/models';
  target.hash = '';
  for (const param of [...target.searchParams.keys()]) {
    if (/^(?:key|api[_-]?key|access_token)$/i.test(param)) {
      throw new Error('请移除 URL 中的密钥参数，改填在 API 密钥栏。');
    }
  }
  target.searchParams.delete('pageToken');
  const headers = key ? (google ? { 'x-goog-api-key': key } : { Authorization: 'Bearer ' + key }) : {};
  const models = new Set();
  const pages = new Set();
  let next;
  do {
    if (next) {
      if (pages.has(next)) throw new Error('站点返回了重复的模型分页。');
      pages.add(next);
      target.searchParams.set('pageToken', next);
    }
    let response, data;
    try {
      response = await request(target.href, {
        method: 'GET', headers, credentials: 'omit', redirect: 'error', cache: 'no-store',
        signal: AbortSignal.timeout(15000),
      });
      if (response.ok) data = await response.json();
    } catch {
      throw new Error('无法读取模型列表，请检查站点、密钥或跨域访问，也可以手动填写模型。');
    }
    if (!response.ok) throw new Error('模型列表请求失败（HTTP ' + response.status + '），原有配置已保留。');
    const list = google ? data?.models : (data?.data ?? data?.models);
    if (!Array.isArray(list)) throw new Error('站点没有返回可识别的模型列表。');
    for (const item of list) {
      const name = google ? item?.name : isText(item) ? item : item?.id ?? item?.model ?? item?.name;
      if (isText(name) && name.trim()) models.add(google ? name.replace(/^models\//, '') : name.trim());
    }
    next = google && isText(data.nextPageToken) ? data.nextPageToken : undefined;
  } while (next);
  return [...models].sort();
}

export { emptyCatalog, readCatalog, migrateCatalog, mergeCatalogs, validateCatalog, discoverModels };

const managerNamespace = 'st-api-manager';
const catalogKey = 'st_api_manager_catalog_v2';
const legacyAccountKey = 'st_api_manager_sync_v1';
const accountKey = 'st_api_manager_sync_v2';
const storageEntry = { namespace: managerNamespace, key: 'state' };
const legacyStorageKeys = [
  'api_configs_manager', 'api_configs_categories', 'api_configs_collapsed_categories',
  'api_configs_category_switch_indexes', 'stb_api_management_settings', 'api_configs_invalid_issues',
  'st_api_manager_sync_metadata_v1', 'st_api_manager_tt_secret_bindings_v1',
];

async function openCatalogStorage(host, context, browserStorage) {
  const store = host.__TAURITAVERN__?.api?.extension?.store;
  if (host.__TAURITAVERN__ && !store) throw new Error('当前 TT 没有扩展存储，原有配置未改动。');
  const extension = context.extensionSettings;
  const saved = store ? await store.tryGetJson(storageEntry) : {
    found: Object.hasOwn(extension, managerNamespace), value: extension[managerNamespace],
  };
  if (saved.found && (saved.value?.version !== 1 || !isObject(saved.value.values))) throw formatError();
  let values = saved.found ? { ...saved.value.values } : {};
  if (!saved.found) {
    for (const key of legacyStorageKeys) {
      const value = browserStorage.getItem(key);
      if (value !== null) values[key] = value;
    }
  }
  let state = {
    catalog: emptyCatalog(),
    sync: { revision: null, pending: false },
  };
  let pendingWrite = Promise.resolve();
  const persist = async next => {
    const nextValues = { ...values, [catalogKey]: JSON.stringify(next) };
    const value = { version: 1, values: nextValues };
    if (store) {
      try { await store.setJson({ ...storageEntry, value }); }
      catch { throw new Error('TT 配置保存失败，请重试。'); }
    }
    else {
      const previous = extension[managerNamespace];
      extension[managerNamespace] = value;
      try { context.saveSettingsDebounced(); }
      catch {
        if (previous === undefined) delete extension[managerNamespace];
        else extension[managerNamespace] = previous;
        throw new Error('ST 配置保存失败，请重试。');
      }
    }
    values = nextValues;
    state = next;
  };
  const transact = fn => {
    pendingWrite = pendingWrite.catch(() => {}).then(fn);
    return pendingWrite;
  };

  if (Object.hasOwn(values, catalogKey)) {
    const parsed = JSON.parse(values[catalogKey]);
    if (!isObject(parsed?.sync) || (parsed.sync.revision !== null && !isText(parsed.sync.revision))
        || typeof parsed.sync.pending !== 'boolean') throw formatError();
    state = { catalog: validateCatalog(parsed.catalog), sync: parsed.sync };
  } else if (Object.keys(values).length) {
    const oldConfigs = JSON.parse(values.api_configs_manager ?? '[]');
    const oldGroups = JSON.parse(values.api_configs_categories ?? '[]');
    const catalog = migrateCatalog(oldConfigs, oldGroups);
    await persist({ catalog, sync: { revision: null, pending: true } });
  }

  const account = context.accountStorage;
  const canSync = typeof account?.getItem === 'function' && typeof account?.setItem === 'function';
  async function remote() {
    let current, raw;
    try {
      current = await account.getItem(accountKey);
      raw = current ?? await account.getItem(legacyAccountKey);
    } catch { throw new Error('读取酒馆账户存储失败。'); }
    if (raw == null) return null;
    let value;
    try { value = JSON.parse(raw); } catch { throw formatError(); }
    if (!isText(value?.revision) || !value.revision) throw formatError();
    if (current != null) return { revision: value.revision, catalog: validateCatalog(value.catalog), legacy: false };
    if (value.version !== 1 || !Array.isArray(value.configs) || !Array.isArray(value.categories)) throw formatError();
    return { revision: 'legacy:' + value.revision, catalog: migrateCatalog(value.configs, value.categories), legacy: true };
  }
  return {
    get catalog() { return state.catalog; },
    canSync,
    flush: () => pendingWrite,
    update: change => transact(async () => {
      const catalog = validateCatalog(change(state.catalog));
      await persist({ catalog, sync: { ...state.sync, pending: true } });
    }),
    pull: () => transact(async () => {
      if (!canSync) throw new Error('当前酒馆不支持账户存储。');
      const incoming = await remote();
      if (!incoming) return '账户还没有同步数据。';
      if (incoming.revision === state.sync.revision) return '已读取此账户版本。';
      // If both copies have work, keep both. A clean client can adopt a later
      // published snapshot, including intentional removals from another client.
      const combine = state.sync.pending || state.sync.revision === null || incoming.legacy;
      const catalog = combine ? mergeCatalogs(state.catalog, incoming.catalog, incoming.legacy) : incoming.catalog;
      const pending = canonical(catalog) !== canonical(incoming.catalog) || incoming.legacy;
      await persist({ catalog, sync: { revision: incoming.revision, pending } });
      return pending ? '已合并账户与本机配置；可将合并后的版本同步到账户。' : '已从账户读取配置。';
    }),
    push: () => transact(async () => {
      if (!canSync) throw new Error('当前酒馆不支持账户存储。');
      const incoming = await remote();
      if ((incoming?.revision ?? null) !== state.sync.revision) {
        throw new Error('账户上有尚未读取的数据。请先点「从账户读取」，再上传合并后的配置。');
      }
      const revision = makeId();
      try { await account.setItem(accountKey, JSON.stringify({ revision, catalog: state.catalog })); }
      catch { throw new Error('写入酒馆账户存储失败。'); }
      await persist({ catalog: state.catalog, sync: { revision, pending: false } });
      return '已写入酒馆账户存储。';
    }),
  };
}

export { openCatalogStorage };

function mountCatalogPanel(host, storage) {
  const doc = host.document;
  function node(tag, text, attributes = {}) {
    const element = doc.createElement(tag);
    if (text !== undefined) element.textContent = text;
    for (const [key, value] of Object.entries(attributes)) element.setAttribute(key, value);
    return element;
  }
  const button = (text, click) => {
    const element = node('button', text, { type: 'button', class: 'menu_button' });
    element.addEventListener('click', click);
    return element;
  };
  const dialog = node('dialog', undefined, { class: 'st-api-manager', 'aria-label': 'API 管理器' });
  const heading = node('header');
  const body = node('section');
  const status = node('p', '', { role: 'status' });
  dialog.append(heading, status, body);
  const style = node('style', `
.st-api-manager{width:min(48rem,calc(100% - 1.5rem));max-height:calc(100% - 1.5rem);box-sizing:border-box;
 color:var(--SmartThemeBodyColor,#f1f1f1);background:var(--SmartThemeBlurTintColor,#26272a);
 border:1px solid var(--SmartThemeBorderColor,#999);border-radius:.65rem;padding:1rem;overflow:auto}
.st-api-manager::backdrop{background:#0009}
.st-api-manager header,.st-api-manager .actions{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap}
.st-api-manager header h2{margin:.25rem auto .25rem 0}
.st-api-manager input,.st-api-manager select,.st-api-manager textarea{font:inherit;max-width:100%;box-sizing:border-box}
.st-api-manager label.field{display:grid;gap:.3rem;margin:.55rem 0}
.st-api-manager article{border-top:1px solid var(--SmartThemeBorderColor,#999);padding:.65rem 0;overflow-wrap:anywhere}
.st-api-manager article p,.st-api-manager [role=status]{margin:.35rem 0}
.st-api-manager fieldset{margin:.65rem 0;border:1px solid var(--SmartThemeBorderColor,#999)}
.st-api-manager fieldset label{display:block;overflow-wrap:anywhere}
.st-api-manager details{margin:.75rem 0}
.st-api-manager .menu_button{min-height:2rem;white-space:normal}
`);
  doc.head.append(style);
  doc.body.append(dialog);
  let filter = '';
  let search = '';
  let busy = false;

  function message(text) { status.textContent = text; }
  function title(text, back) {
    heading.replaceChildren(node('h2', text), button(back ? '返回' : '关闭', () => {
      if (busy) return;
      if (back) { message(''); list(); }
      else dialog.close();
    }));
  }
  function actions(...children) {
    const element = node('div', undefined, { class: 'actions' });
    element.append(...children);
    return element;
  }
  function field(form, label, control) {
    const wrapper = node('label', label, { class: 'field' });
    wrapper.append(control);
    form.append(wrapper);
    return control;
  }
  function input(value = '', attributes = {}) {
    const element = node('input', undefined, { class: 'text_pole', autocomplete: 'off', ...attributes });
    element.value = value;
    return element;
  }
  function select(options, value) {
    const element = node('select');
    for (const [id, name] of options) element.append(node('option', name, { value: id }));
    element.value = value;
    return element;
  }
  async function run(action, success, done = list) {
    if (busy) return;
    busy = true;
    const controls = [...dialog.querySelectorAll('button,input,select,textarea')].filter(item => !item.disabled);
    for (const item of controls) item.disabled = true;
    try {
      const result = await action();
      message(success ?? result);
      done();
    } catch (error) {
      message(error.message || '操作失败，原有配置已保留。');
    } finally {
      busy = false;
      for (const item of controls) item.disabled = false;
    }
  }
  const update = change => storage.update(change);

  function list() {
    const { groups, entries } = storage.catalog;
    if (!['', ':unassigned'].includes(filter) && !groups.some(group => group.id === filter)) filter = '';
    title('API 管理器');
    const file = node('input', undefined, { type: 'file', accept: '.json,application/json', hidden: '' });
    file.addEventListener('change', () => {
      const selected = file.files[0];
      file.value = '';
      if (!selected) return;
      run(async () => {
        let decoded;
        try { decoded = readCatalog(JSON.parse(await selected.text())); } catch { throw formatError(); }
        await update(local => mergeCatalogs(local, decoded.catalog, decoded.legacy));
      }, '已合并导入配置。');
    });
    const pull = button('从账户读取', () => run(() => storage.pull()));
    const push = button('同步到账户', () => run(() => storage.push()));
    pull.disabled = push.disabled = !storage.canSync;
    const toolbar = actions(
      button('新增配置', () => editor()), button('管理分组', groupsPanel),
      button('导入', () => file.click()), button('导出', download), pull, push,
    );
    body.replaceChildren(toolbar, file);
    if (!storage.canSync) body.append(node('p', '当前酒馆未提供账户存储，可通过文件导入和导出。'));
    const groupOptions = [['', '全部分组'], [':unassigned', '未分组'], ...groups.map(group => [group.id, group.name])];
    const groupFilter = select(groupOptions, filter);
    groupFilter.setAttribute('aria-label', '按分组筛选');
    const query = input(search, { type: 'search', placeholder: '搜索站点、模型或分组', 'aria-label': '搜索配置' });
    const cards = node('div', undefined, { class: 'entries' });
    groupFilter.addEventListener('change', () => { filter = groupFilter.value; renderRows(); });
    query.addEventListener('input', () => { search = query.value; renderRows(); });
    body.append(actions(groupFilter, query), cards);
    function renderRows() {
      cards.replaceChildren();
      for (const row of entries) {
        const names = groups.filter(group => row.groupIds.includes(group.id)).map(group => group.name);
        if (filter === ':unassigned' ? row.groupIds.length > 0 : filter && !row.groupIds.includes(filter)) continue;
        if (![row.site, row.name, row.source, row.model, ...names].join(' ').toLowerCase().includes(search.trim().toLowerCase())) continue;
        const card = node('article', undefined, { 'data-entry-id': row.id });
        card.append(
          node('strong', row.model || '未指定模型'),
          node('p', [row.site, row.name, row.source].filter(Boolean).join(' · ')),
          node('p', (row.key ? '已保存密钥' : '未填写密钥') + ' · ' + (names.join('、') || '未分组')),
          actions(button('编辑', () => editor(row)), button('删除', () => {
            if (host.confirm('删除这一条配置？')) run(() => update(catalog => ({
              ...catalog, entries: catalog.entries.filter(entry => entry.id !== row.id),
            })), '已删除配置。');
          })),
        );
        cards.append(card);
      }
      if (!cards.childElementCount) cards.append(node('p', '没有匹配的配置。'));
    }
    renderRows();
  }

  function editor(existing) {
    const row = existing ?? { site: '', name: '', source: 'custom', url: '', key: '', model: '', groupIds: [] };
    title(existing ? '编辑配置' : '新增配置', true);
    message('');
    const form = node('form');
    const site = field(form, '站点名称', input(row.site, { required: '' }));
    const name = field(form, '条目备注（可选）', input(row.name));
    const sources = [['custom', '自定义（OpenAI 兼容）'], ['openai', 'OpenAI'], ['deepseek', 'DeepSeek'], ['makersuite', 'Google AI Studio']];
    if (!sources.some(([id]) => id === row.source)) sources.push([row.source, row.source]);
    const source = field(form, '来源', select(sources, row.source));
    const url = field(form, '站点 URL', input(row.url, { spellcheck: 'false', inputmode: 'url' }));
    const key = field(form, 'API 密钥', input(row.key, { type: 'password', spellcheck: 'false' }));
    const reveal = button('显示密钥', () => {
      const hidden = key.type === 'password';
      key.type = hidden ? 'text' : 'password';
      reveal.textContent = hidden ? '隐藏密钥' : '显示密钥';
    });
    const modelInput = existing ? input(row.model) : node('textarea', undefined, { class: 'text_pole', rows: '3' });
    const model = field(form, existing ? '模型' : '模型（每行一个，可留空）', modelInput);
    const draft = () => ({
      source: source.value, url: existing && url.value === row.url ? row.url : url.value.trim(),
      key: key.value,
    });
    const suggestions = select([['', '可选择拉取到的模型']], '');
    suggestions.setAttribute('aria-label', '拉取到的模型');
    suggestions.hidden = true;
    for (const control of [source, url, key]) control.addEventListener('input', () => { suggestions.hidden = true; });
    suggestions.addEventListener('change', () => {
      if (!suggestions.value) return;
      model.value = existing ? suggestions.value : labels([...model.value.split(/\r?\n/).map(value => value.trim()), suggestions.value]).join('\n');
      suggestions.value = '';
    });
    const pull = button('拉取模型', () => run(async () => {
      suggestions.hidden = true;
      const models = await discoverModels(draft(), host.fetch.bind(host));
      suggestions.replaceChildren(node('option', '可选择拉取到的模型', { value: '' }),
        ...models.map(value => node('option', value, { value })));
      suggestions.hidden = models.length === 0;
      return models.length ? '已拉取 ' + models.length + ' 个模型，选择后再保存。' : '站点没有返回模型，可以手动填写。';
    }, undefined, () => {}));
    form.append(actions(reveal, pull, suggestions));
    const groupBox = node('fieldset');
    groupBox.append(node('legend', '分组（可多选）'));
    const checkboxes = storage.catalog.groups.map(group => {
      const label = node('label');
      const control = input(group.id, { type: 'checkbox' });
      control.checked = row.groupIds.includes(group.id);
      label.append(control, doc.createTextNode(' ' + group.name));
      groupBox.append(label);
      return control;
    });
    if (!checkboxes.length) groupBox.append(node('span', '可先在「管理分组」中创建分组。'));
    if (row.history) {
      const history = node('details');
      history.append(node('summary', '旧密钥池记录'), node('p',
        '原密钥位置：' + (row.history.index + 1) + ' / ' + row.history.poolSize +
        '；历史成功：' + (row.history.keyHistory?.successCount ?? '—') +
        '；历史失败：' + (row.history.keyHistory?.failureCount ?? '—')));
      form.append(history);
    }
    form.append(groupBox, node('button', '保存配置', { type: 'submit', class: 'menu_button' }));
    form.addEventListener('submit', event => {
      event.preventDefault();
      run(() => {
        const fields = draft();
        if ((!existing || fields.url !== row.url || fields.source !== row.source) &&
            (fields.url || fields.source === 'custom')) endpointUrl(fields.url);
        if (!site.value.trim()) throw new Error('请填写站点名称。');
        const models = existing ? [model.value === row.model ? row.model : model.value.trim()]
          : labels(model.value.split(/\r?\n/).map(value => value.trim()));
        const groupIds = checkboxes.filter(control => control.checked).map(control => control.value);
        const rows = (models.length ? models : ['']).map(value => ({
          ...row, ...fields, id: existing?.id ?? makeId(), site: site.value.trim(),
          name: name.value.trim(), model: value, groupIds,
        }));
        return update(catalog => ({
          ...catalog,
          entries: existing ? catalog.entries.map(entry => entry.id === existing.id ? rows[0] : entry) : [...catalog.entries, ...rows],
        }));
      }, '已保存配置。');
    });
    body.replaceChildren(form);
    site.focus();
  }

  function groupsPanel() {
    title('管理分组', true);
    const form = node('form');
    const name = field(form, '新分组名称', input('', { required: '' }));
    form.append(node('button', '创建分组', { type: 'submit', class: 'menu_button' }));
    form.addEventListener('submit', event => {
      event.preventDefault();
      run(() => {
        if (!name.value.trim()) throw new Error('请填写分组名称。');
        return update(catalog => ({
          ...catalog, groups: [...catalog.groups, { id: makeId(), name: name.value.trim() }],
        }));
      }, '已创建分组。', groupsPanel);
    });
    body.replaceChildren(form);
    for (const group of storage.catalog.groups) {
      const label = input(group.name, { 'aria-label': '分组名称：' + group.name });
      body.append(actions(label, button('保存名称', () => run(() => {
        if (!label.value.trim()) throw new Error('请填写分组名称。');
        return update(catalog => ({
          ...catalog, groups: catalog.groups.map(item => item.id === group.id ? { ...item, name: label.value.trim() } : item),
        }));
      }, '已保存分组。', groupsPanel)), button('删除分组', () => {
        if (host.confirm('删除这个分组？其中的配置会保留。')) run(() => update(catalog => ({
          ...catalog, groups: catalog.groups.filter(item => item.id !== group.id),
          entries: catalog.entries.map(row => ({ ...row, groupIds: row.groupIds.filter(id => id !== group.id) })),
        })), '已删除分组。', groupsPanel);
      })));
    }
  }

  function download() {
    const blob = new Blob([JSON.stringify(storage.catalog, null, 2)], { type: 'application/json' });
    const href = URL.createObjectURL(blob);
    const link = node('a', undefined, { href, download: 'st-api-manager-configs.json' });
    dialog.append(link);
    link.click();
    link.remove();
    host.setTimeout(() => URL.revokeObjectURL(href), 1000);
    message('已导出配置，文件包含密钥。');
  }
  dialog.addEventListener('cancel', event => { if (busy) event.preventDefault(); });
  dialog.addEventListener('close', () => { if (!dialog.open) body.replaceChildren(); });
  return () => {
    if (dialog.open) return;
    message('');
    list();
    dialog.showModal();
  };
}

async function startCatalogManager(host, browserStorage) {
  await (host.__TAURITAVERN__?.ready ?? host.__TAURITAVERN_MAIN_READY__);
  const doc = host.document;
  if (doc.readyState === 'loading') await new Promise(resolve => doc.addEventListener('DOMContentLoaded', resolve, { once: true }));
  const context = host.SillyTavern.getContext();
  const storage = await openCatalogStorage(host, context, browserStorage);
  const open = mountCatalogPanel(host, storage);
  function entry(selector, id) {
    const container = doc.querySelector(selector);
    if (!container || doc.getElementById(id)) return;
    const button = doc.createElement('button');
    button.id = id;
    button.type = 'button';
    button.className = 'menu_button interactable';
    button.textContent = 'API 管理器';
    button.addEventListener('click', event => { event.stopPropagation(); open(); });
    container.append(button);
  }
  entry('#extensionsMenu', 'st-api-manager-extension-button');
  entry('#openai_settings', 'st-api-manager-connection-button');
  const callback = async () => { open(); return ''; };
  if (context.SlashCommandParser && context.SlashCommand) {
    context.SlashCommandParser.addCommandObject(context.SlashCommand.fromProps({ name: 'st-api-manager', callback, helpString: '打开 API 管理器' }));
  } else {
    context.registerSlashCommand?.('st-api-manager', callback, [], '打开 API 管理器', false, true);
  }
  host.addEventListener('st-api-manager-open-request', open);
  return { open, flush: storage.flush };
}

const manager = await startCatalogManager(window.parent || window, window.localStorage);
export const initApiManager = manager.open;
export const flushTauriTavernStorage = manager.flush;
